/**
 * 자동 생성 — `node scripts/gen-og-glyphs.mjs`. 손으로 고치지 말 것.
 *
 * 초대 카드(`ogCard.ts`)가 방 코드를 찍는 데 쓰는 글자 그림판이다. 글자 하나가
 * 154×222 알파 비트맵이고, 32개가 `OG_GLYPH_CHARS` 순서대로 이어 붙어 있다
 * (0 = 종이, 255 = 잉크). 왜 비트맵인지는 생성기 주석을 보라.
 */

/** 그림판에 들어 있는 글자 — RoomManager 의 CODE_CHARS 와 같다 */
export const OG_GLYPH_CHARS = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";

/** 글자 한 칸의 크기 (px) */
export const OG_GLYPH_W = 154;
export const OG_GLYPH_H = 222;

/** 고정폭 진폭 — 글자를 이 간격으로 늘어놓으면 원래 폰트의 짜임이 된다 */
export const OG_GLYPH_ADVANCE = 151;

/** deflate + base64 로 굳힌 알파 비트맵 32 × 154 × 222 */
export const OG_GLYPH_ATLAS_B64 =
  "";
